with models(product_slug,leaf_type) as (values ('catalog-30','Глухе'),('catalog-31','Глухе'),('catalog-32','Глухе'),('catalog-33','Глухе'),('catalog-34','Глухе'),('catalog-35','Глухе'),('catalog-36','Чорне скло'),('catalog-37','Глухе'),('catalog-38','Глухе'),('catalog-39','Глухе')), specs(product_slug,label,value,sort_order) as (
 select product_slug,'Тип виробу','Міжкімнатні двері',100 from models union all select product_slug,'Тип полотна',leaf_type,110 from models union all select product_slug,'Покриття','ПВХ плівка',120 from models union all select product_slug,'Товщина полотна','44 мм',130 from models union all select product_slug,'Доступні ширини','600 / 700 / 800 / 900 мм',140 from models union all select product_slug,'Висота полотна','2000 мм',150 from models union all select product_slug,'Відкривання','Розпашні, одностулкові',160 from models union all select product_slug,'Країна виробництва','Україна',170 from models
)
insert into public.product_specs(product_slug,label,value,sort_order) select product_slug,label,value,sort_order from specs on conflict(product_slug,label) do update set value=excluded.value,sort_order=excluded.sort_order,is_active=true;

insert into public.product_sources(product_slug,source_name,source_url,source_product_name,verification_status,verified_at,notes) select slug,'Market Dveri',source_url,source_product_name,'verified',now(),'Модель, виконання та головне фото збігаються.' from (values
